ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS admission_time TIMESTAMPTZ DEFAULT now(); ALTER TABLE public.patients ADD COLUMN IF NOT EXISTS status TEXT DEFAULT 'Admitted'; UPDATE public.patients SET admission_time = COALESCE(admission_time, now()) WHERE admission_time IS NULL; UPDATE public.patients SET status = COALESCE(status, CASE WHEN discharge_time IS NOT NULL THEN 'Discharged' ELSE 'Admitted' END);